/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadCapital(r["bzProcsNo"], r["clmInstSeq"], r["comNm"], r["invstChgTpCd"], r["invstDd"], r["invstSaleShrs"], r["pershrInvstSaleAmt"], r["stkNm"], r["incdecRsn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistEtcForm || { elements: [] });
        if (($c.util.getComponent('dma_RegisterReq').get('nowPage')) > ($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd'))) {
            return;
        }
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05005c.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelistEtc.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_resultList_fmt_invstDd
 * @description grd result List fmt invst Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name loadCapital
 * @description load Capital 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} clmInstSeq clmInstSeq
 * @param {String} comNm comNm
 * @param {String} invstChgTpCd invstChgTpCd
 * @param {String} invstDd invstDd
 * @param {*} invstSaleShrs invstSaleShrs
 * @param {*} pershrInvstSaleAmt pershrInvstSaleAmt
 * @param {String} stkNm stkNm
 * @param {*} incdecRsn incdecRsn
 * @returns {void}
 * @hidden N
 */
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('clmInstSeq', clmInstSeq);
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    (($c.util.getComponent('slc_invstChgTpCd'))?.setValue?.(invstChgTpCd));
    $c.util.getComponent('cal_invstDd').setValue($c.date.dateUnFormat(invstDd));
    $c.util.getComponent('ipt_invstSaleShrs').setValue($c.num.formatNumber(invstSaleShrs));
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue($c.num.formatNumber(pershrInvstSaleAmt));
    (($c.util.getComponent('slc_stkNm'))?.setValue?.(stkNm));
    (($c.util.getComponent('slc_incdecRsn'))?.setValue?.(incdecRsn));
    scwin.onloadDataSet();
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if (($c.util.getComponent('ipt_comNm').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm').getValue())) === '') {
        await $c.win.alert("회사명을 입력하십시요.");
        $c.util.getComponent("ipt_comNm").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if ($c.util.getComponent('cal_invstDd').getValue().length !== 8) {
        await $c.win.alert("투자/매각일을 정확히 입력해주십시요.");
        $c.util.getComponent("cal_invstDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_invstSaleShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_invstSaleShrs').getValue())) === '') {
        await $c.win.alert("주식수를 입력하세요.");
        $c.util.getComponent("ipt_invstSaleShrs").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_pershrInvstSaleAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_pershrInvstSaleAmt').getValue())) === '') {
        await $c.win.alert("주당투자금액을 입력하세요.");
        $c.util.getComponent("ipt_pershrInvstSaleAmt").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return;
    }
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.setDataMergeDate();
    scwin.form.action = '/list/prelistEtc.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistRegEtc');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name setInitData
 * @description set Init Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInitData = function () {
    $c.util.getComponent('ipt_comNm').setValue("테스트회사");
    $c.util.getComponent('cal_invstDd').setValue("20080930");
    $c.util.getComponent('ipt_invstSaleShrs').setValue("1234567");
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue("1234567");
    scwin.onloadDataSet();
};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    scwin.form.action       = '/list/prelistPage.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistPageSearch');
    await moveUrl('/list/prelistPage.do', {});

};

/**
 * @method
 * @name new56
 * @description new56 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new56 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

    $c.util.getComponent('dma_RegisterReq').set('transKind', 0); // 신규: 0 , 수정 : 1

    // ??? 조회 목록중에 청구일련번호 같은것이 있는지 체크 필

    await scwin.register() ;

};
